package com.cpe.simulator.desktop.ui;

import javafx.scene.image.Image;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;

/**
 * Loads the application icon set generated by IconGenerator
 * (src/main/resources/icons). Returns null when icons are absent so the UI
 * degrades gracefully instead of failing to start.
 */
public final class AppIcons {

    private static final int[] SIZES = {16, 32, 48, 256};

    private AppIcons() {
    }

    public static Image load(int size) {
        String path = "/icons/app-icon-" + size + ".png";
        try (InputStream is = AppIcons.class.getResourceAsStream(path)) {
            return is != null ? new Image(is) : null;
        } catch (Exception e) {
            return null;
        }
    }

    public static List<Image> all() {
        List<Image> icons = new ArrayList<>();
        for (int size : SIZES) {
            Image image = load(size);
            if (image != null) {
                icons.add(image);
            }
        }
        return icons;
    }
}
